 private static final Paint p=new Paint();private static final Path path=new Path();
 private static final LinkedHashMap<String,Bitmap> cache=new LinkedHashMap<String,Bitmap>(MAX_FRAMES,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,Bitmap> e){return size()>MAX_FRAMES;}};
 static boolean supported(String kind){for(String k:KINDS)if(k.equals(kind))return true;return false;}
 static int cachedFrames(){return cache.size();}
 static float headTop(String kind){return kind.equals("horse")?-96:kind.equals("warBear")?-76:kind.equals("familiar")?-94:kind.equals("raven")?-68:-62;}
 static int direction(float dx,float dy){float sx=dx-dy,sy=(dx+dy)*.5f;return Math.abs(sx)>Math.abs(sy)*1.5?(sx<0?3:2):(sy<0?1:0);}
 static boolean draw(Canvas c,JSONObject pet,float phase,float attack){String kind=pet.optString("kind");if(!supported(kind))return false;int row=direction((float)pet.optDouble(attack>=0?"attackDX":"facingDX",1),(float)pet.optDouble(attack>=0?"attackDY":"facingDY",0));Bitmap b=frame(kind,row,ClassSprites.walkFrame(phase,pet.optBoolean("active")),ClassSprites.attackFrame(attack));p.setColor(Color.WHITE);c.drawBitmap(b,null,new RectF(-56,-100,56,12),p);return true;}
 static boolean preview(Canvas c,JSONObject pet,RectF bounds){String kind=pet.optString("kind");if(!supported(kind))return false;Bitmap b=frame(kind,2,0,-1);float scale=Math.min(bounds.width()/WIDTH,bounds.height()/HEIGHT),width=WIDTH*scale,height=HEIGHT*scale;p.setColor(Color.WHITE);c.drawBitmap(b,null,new RectF(bounds.centerX()-width/2,bounds.bottom-height,bounds.centerX()+width/2,bounds.bottom),p);return true;}
 static Bitmap frame(String kind,int row,int walk,int attack){row=(row%4+4)%4;walk=Math.max(0,Math.min(4,walk));attack=Math.max(-1,Math.min(3,attack));String key=kind+":"+row+":"+walk+":"+attack;Bitmap b=cache.get(key);if(b!=null)return b;b=Bitmap.createBitmap(WIDTH,HEIGHT,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.scale(2,2);c.translate(56,100);if(row==3)c.scale(-1,1);if(kind.equals("raven"))raven(c,row,walk,attack);else if(kind.equals("familiar"))familiar(c,row,walk,attack);else quadruped(c,kind,row,walk,attack);cache.put(key,b);return b;}
 private static void rect(Canvas c,int color,float x,float y,float width,float height){p.setColor(color);c.drawRect(x,y,x+width,y+height,p);}
 private static void poly(Canvas c,int color,float... v){p.setColor(color);path.reset();path.moveTo(v[0],v[1]);for(int i=2;i<v.length;i+=2)path.lineTo(v[i],v[i+1]);path.close();c.drawPath(path,p);}
 private static void line(Canvas c,int color,float width,float x,float y,float xx,float yy){p.setColor(color);p.setStrokeWidth(width);c.drawLine(x,y,xx,yy,p);}
 private static int shade(int color,int amount){return Color.rgb(Math.max(0,Math.min(255,Color.red(color)+amount)),Math.max(0,Math.min(255,Color.green(color)+amount)),Math.max(0,Math.min(255,Color.blue(color)+amount)));}
