  poly(c,edge,-32,top+5,-22,top-3,11,top-2,29,top+8,26,top+26,-23,top+27,-34,top+17);poly(c,coat,-31,top+6,-21,top,11,top+1,27,top+9,24,top+23,-21,top+24,-31,top+16);poly(c,light,-25,top+5,-10,top+2,11,top+4,21,top+10,-20,top+14);poly(c,dark,-30,top+17,-6,top+17,19,top+12,24,top+23,-21,top+24);
