   if(dire||bear){poly(c,0xff222b2c,-23,top+1,-9,top-4,12,top,19,top+16,-16,top+19);poly(c,0xff5c6260,-22,top+2,-8,top-2,10,top+2,15,top+13,-15,top+15);for(int x=-19;x<12;x+=6){line(c,0xffb0b0a1,1,x,top+3,x+3,top+12);rect(c,gold,x+2,top+5,1,1);}line(c,0xff8c6b44,3,-14,top+17,14,top+8);rect(c,gold,3,top+8,4,4);}
